using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Reflection;using System.Security.Cryptography;using System.Text.Json;using WorldGenesis.Simulation;
class Program {
 static JsonSerializerOptions json=new JsonSerializerOptions{IncludeFields=true,WriteIndented=true};
 static string Hash(string p)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p)));
 static int Main(string[] args){
#if FAUNA_SCENARIOS
 if(args.Length>0&&args[0]=="--tests")return Scenarios.Run(args.Length>1?args[1]:"Evidence/Simulation/fauna-placement-tests.json");
#endif
string output=args.Length>0?args[0]:"Evidence/Simulation/fauna-natural.json";int seconds=args.Length>1?int.Parse(args[1]):1200;string source=args.Length>2?args[2]:"WorldGenesis/Assets/_Project/Scripts/Simulation";var hashes=Directory.GetFiles(source,"*.cs",SearchOption.AllDirectories).ToDictionary(p=>p,p=>Hash(p));var rows=new List<object>();bool all=true;
 foreach(int seed in new[]{1618033,271828,944}){var timer=Stopwatch.StartNew();var w=WorldGenerator.Generate(seed,128,128);var e=new SimulationEngine(w);var seen=new HashSet<int>();int births=0,arrivals=0,deaths=0,peak=0;var timeline=new List<object>();bool valid=true;string error=null;
 for(int tick=0;tick<seconds*10;tick++){var prior=new HashSet<int>(w.Units.Where(u=>WildlifeCatalog.IsAnimal(u.Species)).Select(u=>u.Id));e.Step(.1f);var current=new HashSet<int>();foreach(var u in w.Units){if(!WildlifeCatalog.IsAnimal(u.Species))continue;current.Add(u.Id);if(seen.Add(u.Id)){if(u.Age<.1f)births++;else arrivals++;}}deaths+=prior.Count(id=>!current.Contains(id));peak=Math.Max(peak,current.Count);if(w.Tick%600==0)timeline.Add(new{seconds=w.Tick*.1f,population=current.Count,births,arrivals,deaths});if(w.Tick%100==0&&!w.Validate(out error)){valid=false;break;}if(timer.Elapsed.TotalSeconds>120){error="wall limit120s";valid=false;break;}}
 all &=valid;rows.Add(new{seed,tick=w.Tick,population=w.Units.Count(u=>WildlifeCatalog.IsAnimal(u.Species)),births,arrivals,deaths,peak,valid,error,wallSeconds=timer.Elapsed.TotalSeconds,timeline});Console.WriteLine(seed+" peak="+peak+" population="+w.Units.Count+" born="+births+" immigrated="+arrivals+" dead="+deaths+" valid="+valid);}
 bool unchanged=hashes.All(kv=>File.Exists(kv.Key)&&Hash(kv.Key)==kv.Value);Directory.CreateDirectory(Path.GetDirectoryName(output));File.WriteAllText(output,JsonSerializer.Serialize(new{utc=DateTime.UtcNow,source,sourceUnchanged=unchanged,sourceSHA256=hashes,assemblySHA256=Hash(Assembly.GetExecutingAssembly().Location),seconds,passed=all,assistance="Generated Island128x128. No citizens, animals, resources or technologies spawned by fixture; default laws and weather; only Step(.1). Births vs immigration classified by first-observed Age<.1, deaths by removed actual IDs. Offline ecology isolation, not native FPS or settlement benchmark.",results=rows},json));return all&&unchanged?0:1;}}
